"""Shared git hooks: installed once per clone, resolved per worktree."""

import os
import subprocess
from pathlib import Path

import pytest

from commonplace.guards import hooks

IDENTITY = {
    "GIT_AUTHOR_NAME": "t",
    "GIT_AUTHOR_EMAIL": "t@example.invalid",
    "GIT_COMMITTER_NAME": "t",
    "GIT_COMMITTER_EMAIL": "t@example.invalid",
}
# What `pre-commit install` writes: one absolute interpreter, else pre-commit on PATH.
PRE_COMMIT_GENERATED = """#!/usr/bin/env bash
# File generated by pre-commit: https://pre-commit.com
INSTALL_PYTHON=/nonexistent/other-worktree/.venv/bin/python
if [ -x "$INSTALL_PYTHON" ]; then
    exec "$INSTALL_PYTHON" -mpre_commit hook-impl
elif command -v pre-commit > /dev/null; then
    exec pre-commit hook-impl
else
    echo '`pre-commit` not found.  Did you forget to activate your virtualenv?' 1>&2
    exit 1
fi
"""
# A stand-in interpreter: imports succeed, every other call is logged.
FAKE_PYTHON = """#!/bin/sh
if [ "$1" = "-c" ]; then exit "${FAKE_IMPORT_EXIT:-0}"; fi
echo "$0 cwd=$(pwd) args: $*" >> "$HOOK_LOG"
cat > /dev/null
exit "${FAKE_RUN_EXIT:-0}"
"""


def git(cwd, *args, check=True, env=None):
    return subprocess.run(
        ["git", "-C", str(cwd), *args],
        capture_output=True,
        text=True,
        check=check,
        env=env or dict(os.environ, **IDENTITY),
    )


@pytest.fixture
def clone(tmp_path, monkeypatch):
    top = tmp_path / "clone"
    top.mkdir()
    git(top, "init", "-q", "-b", "main")
    (top / "f.txt").write_text("1\n")
    git(top, "add", "-A")
    git(top, "-c", "core.hooksPath=/dev/null", "commit", "-qm", "base")
    monkeypatch.setenv("HOOK_LOG", str(tmp_path / "hook.log"))
    for name in ("COMMONPLACE_PYTHON", "VIRTUAL_ENV", "FAKE_IMPORT_EXIT", "FAKE_RUN_EXIT"):
        monkeypatch.delenv(name, raising=False)
    return top


def add_worktree(clone, name, with_venv=True):
    work = clone.parent / name
    git(clone, "worktree", "add", "-q", str(work), "-b", name)
    if with_venv:
        py = work / ".venv" / "bin" / "python"
        py.parent.mkdir(parents=True)
        py.write_text(FAKE_PYTHON)
        py.chmod(0o755)
    return work


def hook_env(**extra):
    # A PATH without pre-commit, as in a shell that never activated the clone's venv.
    return dict(os.environ, **IDENTITY, PATH=f"/usr/bin{os.pathsep}/bin", **extra)


def test_install_writes_both_hooks_into_the_shared_hooks_dir(clone):
    work = add_worktree(clone, "wt")
    results = hooks.install(work)
    assert {r.hook: r.action for r in results} == {"pre-commit": "written", "pre-push": "written"}
    for hook in ("pre-commit", "pre-push"):
        path = clone / ".git" / "hooks" / hook
        assert path.is_file() and os.access(path, os.X_OK)
        assert hooks.MARKER in path.read_text()
    assert {r.action for r in hooks.install(clone)} == {"unchanged"}


def test_install_replaces_the_pre_commit_generated_hook_and_keeps_a_custom_one(clone):
    directory = clone / ".git" / "hooks"
    (directory / "pre-commit").write_text(PRE_COMMIT_GENERATED)
    (directory / "pre-push").write_text("#!/bin/sh\necho mine\n")
    actions = {r.hook: r.action for r in hooks.install(clone)}
    assert actions == {"pre-commit": "replaced", "pre-push": "kept"}
    assert "echo mine" in (directory / "pre-push").read_text()
    forced = {r.hook: r.action for r in hooks.install(clone, force=True)}
    assert forced["pre-push"] == "replaced"
    assert "echo mine" in (directory / "pre-push.bak").read_text()


def test_a_fresh_worktree_with_its_own_venv_runs_that_venvs_python(clone):
    hooks.install(clone)
    work = add_worktree(clone, "fresh")
    (work / "g.txt").write_text("2\n")
    git(work, "add", "g.txt")
    proc = git(work, "commit", "-qm", "x", check=False, env=hook_env())
    assert proc.returncode == 0, proc.stderr
    log = Path(os.environ["HOOK_LOG"]).read_text()
    assert f"{work}/.venv/bin/python cwd={work} args: -m pre_commit hook-impl" in log
    assert "--hook-type=pre-commit" in log


def test_the_old_generated_hook_fails_in_that_same_fresh_worktree(clone):
    """The bug being fixed: pre-commit's own hook, in a worktree that has only its .venv."""
    (clone / ".git" / "hooks" / "pre-commit").write_text(PRE_COMMIT_GENERATED)
    (clone / ".git" / "hooks" / "pre-commit").chmod(0o755)
    work = add_worktree(clone, "fresh")
    (work / "g.txt").write_text("2\n")
    git(work, "add", "g.txt")
    proc = git(work, "commit", "-qm", "x", check=False, env=hook_env())
    assert proc.returncode != 0
    assert "`pre-commit` not found" in proc.stderr


def test_a_worktree_without_an_environment_is_told_how_to_set_one_up(clone):
    hooks.install(clone)
    work = add_worktree(clone, "bare", with_venv=False)
    (work / "g.txt").write_text("2\n")
    git(work, "add", "g.txt")
    env = hook_env(FAKE_IMPORT_EXIT="1")
    proc = git(work, "commit", "-qm", "x", check=False, env=env)
    assert proc.returncode == 1
    assert "no Python environment for this worktree has 'pre_commit'" in proc.stderr
    assert f'cd "{work}" && uv sync --extra dev' in proc.stderr
    assert "COMMONPLACE_PYTHON=/path/to/python" in proc.stderr


def test_a_worktree_without_the_quick_check_module_blocks_the_push_with_setup_steps(
    clone, tmp_path
):
    hooks.install(clone)
    remote = tmp_path / "remote.git"
    git(tmp_path, "init", "-q", "--bare", str(remote))
    work = add_worktree(clone, "nomodule")
    git(work, "remote", "add", "origin", str(remote))
    proc = git(
        work, "push", "-q", "origin", "nomodule", check=False, env=hook_env(FAKE_IMPORT_EXIT="1")
    )
    assert proc.returncode != 0
    assert "has 'commonplace.guards.prepush'" in proc.stderr
    assert "uv sync --extra dev" in proc.stderr


def test_pre_push_hook_passes_remote_args_and_stdin_to_the_quick_check(clone, tmp_path):
    hooks.install(clone)
    remote = tmp_path / "remote.git"
    git(tmp_path, "init", "-q", "--bare", str(remote))
    work = add_worktree(clone, "pushy")
    git(work, "remote", "add", "origin", str(remote))
    proc = git(work, "push", "-q", "origin", "pushy", check=False, env=hook_env())
    assert proc.returncode == 0, proc.stderr
    log = Path(os.environ["HOOK_LOG"]).read_text()
    assert "-m commonplace.guards.prepush origin" in log


def test_a_failing_quick_check_blocks_the_push(clone, tmp_path):
    hooks.install(clone)
    remote = tmp_path / "remote.git"
    git(tmp_path, "init", "-q", "--bare", str(remote))
    work = add_worktree(clone, "blocked")
    git(work, "remote", "add", "origin", str(remote))
    proc = git(
        work, "push", "-q", "origin", "blocked", check=False, env=hook_env(FAKE_RUN_EXIT="1")
    )
    assert proc.returncode != 0
    assert git(remote, "branch", "--list", "blocked").stdout.strip() == ""


def test_commonplace_python_overrides_the_worktree_environment(clone, tmp_path):
    hooks.install(clone)
    work = add_worktree(clone, "wt")
    other = tmp_path / "elsewhere" / "python"
    other.parent.mkdir()
    other.write_text(FAKE_PYTHON)
    other.chmod(0o755)
    (work / "g.txt").write_text("2\n")
    git(work, "add", "g.txt")
    git(work, "commit", "-qm", "x", env=hook_env(COMMONPLACE_PYTHON=str(other)))
    assert str(other) in Path(os.environ["HOOK_LOG"]).read_text()


def test_status_names_the_interpreter_a_worktree_would_use(clone):
    hooks.install(clone)
    work = add_worktree(clone, "wt")
    bare = add_worktree(clone, "bare", with_venv=False)
    assert "pre-push: installed" in hooks.status(work)
    assert f"uses {work}/.venv/bin/python" in hooks.status(work)[-1]
    assert "uv sync --extra dev" in hooks.status(bare)[-1]


def test_status_before_install(clone):
    assert hooks.status(clone)[:2] == ["pre-commit: not installed", "pre-push: not installed"]


def test_the_cli_installs_and_reports(clone, capsys, monkeypatch):
    monkeypatch.chdir(clone)
    assert hooks.main(["install"]) == 0
    assert "pre-push: written" in capsys.readouterr().out
    assert hooks.main(["status"]) == 0
    assert "pre-commit: installed" in capsys.readouterr().out
